import{_ as e,o as t,c as s,a2 as p}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_01_overview.png",o="/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_02_path_carrot.png",i="/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_03_geometry_branches.png",l="/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_04_velocity_regulation.png",c="/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_05_rotate_reverse.png",r="/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_06_collision_output.png",P=JSON.parse('{"title":"只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法","description":"Pure Pursuit 的经典画面很简单：在路径前方放一个目标点，机器人不断追它。","frontmatter":{"title":"只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法","description":"Pure Pursuit 的经典画面很简单：在路径前方放一个目标点，机器人不断追它。","date":"2026-07-27","topic":"Nav2 工程实践","section":"三 · 局部控制与速度生成","readingTime":16,"source":"2026-07-27/nav2_regulated_pure_pursuit_controller_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-27/rpp_core_01_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-pure-pursuit-controller-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法"}],["meta",{"property":"og:description","content":"Pure Pursuit 的经典画面很简单：在路径前方放一个目标点，机器人不断追它。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-pure-pursuit-controller-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_01_overview.png"}],["meta",{"property":"article:published_time","content":"2026-07-27"}],["meta",{"name":"twitter:title","content":"只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法"}],["meta",{"name":"twitter:description","content":"Pure Pursuit 的经典画面很简单：在路径前方放一个目标点，机器人不断追它。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/rpp_core_01_overview.png"}]],"prev":{"text":"不选冠军，让 1000 种未来一起投票：Nav2 MPPI 如何炼出一条速度？","link":"/nav2/nav2-mppi-controller-core-algorithm"},"next":{"text":"先别急着走：Nav2 Rotation Shim 如何在路径跟踪前把方向“扶正”？","link":"/nav2/nav2-rotation-shim-controller-core-algorithm"}},"headers":[],"relativePath":"nav2/nav2-regulated-pure-pursuit-controller-core-algorithm.md","filePath":"nav2/nav2-regulated-pure-pursuit-controller-core-algorithm.md","lastUpdated":null}'),d={name:"nav2/nav2-regulated-pure-pursuit-controller-core-algorithm.md"};function h(u,a,g,b,_,m){return t(),s("div",null,[...a[0]||(a[0]=[p('<h1 id="只追一根-胡萝卜-为何还能过急弯、贴窄道-拆解-nav2-rpp-核心算法" tabindex="-1">只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法 <a class="header-anchor" href="#只追一根-胡萝卜-为何还能过急弯、贴窄道-拆解-nav2-rpp-核心算法" aria-label="Permalink to &quot;只追一根“胡萝卜”，为何还能过急弯、贴窄道？拆解 Nav2 RPP 核心算法&quot;">​</a></h1><p>Pure Pursuit 的经典画面很简单：在路径前方放一个目标点，机器人不断追它。</p><p>可如果只按几何追踪，前视点过近会摇摆，急弯容易冲出路径，窄道贴近障碍时仍可能保持高速，接近终点也缺少自然减速。Nav2 的 Regulated Pure Pursuit，简称 RPP，正是在“追胡萝卜”外面加上速度调节、旋转接管、倒车换向和预测碰撞弧，把一个几何控制律变成工程可用的局部控制器。</p><p>RPP 不采样数百条轨迹，也不运行迭代优化。每个控制周期只选择一根 carrot、计算一条圆弧，再决定这条弧该以多快的速度执行，以及在执行前是否会碰撞。</p><p>本文基于当前本地 <code>navigation2</code>、<code>nav2_regulated_pure_pursuit_controller 1.1.20</code> 源码与现用参数，只拆局部路径、动态前视、Pure Pursuit 曲率、三路速度闸门、原地旋转、倒车 cusp 和 Footprint 碰撞预测等核心算法。</p><p><img src="'+n+`" alt="RPP 核心算法总数据流"></p><h2 id="一、rpp-每周期只求一条候选运动弧" tabindex="-1">一、RPP 每周期只求一条候选运动弧 <a class="header-anchor" href="#一、rpp-每周期只求一条候选运动弧" aria-label="Permalink to &quot;一、RPP 每周期只求一条候选运动弧&quot;">​</a></h2><h3 id="_1-1-输入不是一张静态几何题" tabindex="-1">1.1 输入不是一张静态几何题 <a class="header-anchor" href="#_1-1-输入不是一张静态几何题" aria-label="Permalink to &quot;1.1 输入不是一张静态几何题&quot;">​</a></h3><p><code>computeVelocityCommands()</code> 每周期获得：</p><ul><li>当前机器人 Pose。</li><li>当前机器人 Twist。</li><li>当前任务使用的 GoalChecker。</li><li>之前通过 <code>setPlan()</code> 缓存的全局 Path。</li><li>Local Costmap、机器人 Footprint 与 TF。</li></ul><p>它输出一个 <code>TwistStamped</code>，只有前向线速度 <code>linear.x</code> 和角速度 <code>angular.z</code>。</p><p>当前 Twist 并不直接代入 Pure Pursuit 曲率公式，但会影响速度缩放前视距离，也会限制原地旋转分支的单周期角速度变化。</p><h3 id="_1-2-核心链路由几何、调节和安全组成" tabindex="-1">1.2 核心链路由几何、调节和安全组成 <a class="header-anchor" href="#_1-2-核心链路由几何、调节和安全组成" aria-label="Permalink to &quot;1.2 核心链路由几何、调节和安全组成&quot;">​</a></h3><p>RPP 的控制链可以压缩为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全局 Path</span></span>
<span class="line"><span>→ 裁剪并变换到机器人坐标系</span></span>
<span class="line"><span>→ 计算前视距离</span></span>
<span class="line"><span>→ 选择或插值 carrot</span></span>
<span class="line"><span>→ 计算 Pure Pursuit 曲率</span></span>
<span class="line"><span>→ 选择旋转或正常跟踪分支</span></span>
<span class="line"><span>→ 调节线速度</span></span>
<span class="line"><span>→ 预测 Footprint 碰撞</span></span>
<span class="line"><span>→ 输出 TwistStamped</span></span></code></pre></div><p>几何层回答“方向应该弯多少”，速度层回答“这条弧应该跑多快”，碰撞层回答“这个 Twist 能不能执行”。</p><h3 id="_1-3-rpp-不会主动生成绕障替代轨迹" tabindex="-1">1.3 RPP 不会主动生成绕障替代轨迹 <a class="header-anchor" href="#_1-3-rpp-不会主动生成绕障替代轨迹" aria-label="Permalink to &quot;1.3 RPP 不会主动生成绕障替代轨迹&quot;">​</a></h3><p>carrot 必须来自全局 Path。碰撞预测发现障碍时，RPP 抛出异常，不会把 carrot 横向挪开，也不会在障碍两侧生成候选轨迹。</p><p>绕障仍依赖上游规划器重新生成 Path，或者由外部导航编排触发重规划与恢复。RPP 的职责是跟踪、调速和拒绝危险命令，不是局部路径搜索。</p><h3 id="_1-4-当前配置加载了-rpp-但没有默认选择它" tabindex="-1">1.4 当前配置加载了 RPP，但没有默认选择它 <a class="header-anchor" href="#_1-4-当前配置加载了-rpp-但没有默认选择它" aria-label="Permalink to &quot;1.4 当前配置加载了 RPP，但没有默认选择它&quot;">​</a></h3><p>当前 <code>nav2_regulated_modules</code> 一次加载 DWB、RPP、MPPI、GracefulController 和 RotationShimController，但 <code>controller_id</code> 仍为 <code>DWB</code>。</p><p><code>myagv_test_bringup</code> 默认同样是 DWB，<code>mytb3_bringup</code> 默认是 GracefulController。本文分析的是当前已配置的 RPP 算法与参数，不代表现有启动链默认正在使用 RPP。</p><h2 id="二、全局-path-先收缩成机器人附近的局部-path" tabindex="-1">二、全局 Path 先收缩成机器人附近的局部 Path <a class="header-anchor" href="#二、全局-path-先收缩成机器人附近的局部-path" aria-label="Permalink to &quot;二、全局 Path 先收缩成机器人附近的局部 Path&quot;">​</a></h2><p><img src="`+o+`" alt="全局 Path 到局部路径和 carrot"></p><h3 id="_2-1-最近点搜索被累计路径长度限制" tabindex="-1">2.1 最近点搜索被累计路径长度限制 <a class="header-anchor" href="#_2-1-最近点搜索被累计路径长度限制" aria-label="Permalink to &quot;2.1 最近点搜索被累计路径长度限制&quot;">​</a></h3><p>RPP 先把机器人 Pose 变换到全局 Path frame，再调用 <code>first_after_integrated_distance()</code>，只取路径起点向前累计 <code>max_robot_pose_search_dist</code> 的前缀。</p><p>当前参数为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_robot_pose_search_dist = 3.0 m</span></span></code></pre></div><p>随后只在这段前缀中寻找与机器人欧氏距离最近的 Pose。</p><p>这个边界对环形或自交路径很重要。如果在整条 Path 上找最近点，机器人可能被匹配到空间位置很近、但路径进度已经很远的另一段。</p><h3 id="_2-2-局部变换范围由-costmap-最大半边决定" tabindex="-1">2.2 局部变换范围由 Costmap 最大半边决定 <a class="header-anchor" href="#_2-2-局部变换范围由-costmap-最大半边决定" aria-label="Permalink to &quot;2.2 局部变换范围由 Costmap 最大半边决定&quot;">​</a></h3><p>最近点之后的 Path 不会全部变换。源码计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_costmap_extent =</span></span>
<span class="line"><span>  max(costmap_width_m, costmap_height_m) / 2</span></span></code></pre></div><p>当某个 Path Pose 到机器人的欧氏距离超过该值，就停止局部截取。</p><p>这是一条以机器人为圆心的距离边界，半径取 Costmap 最大半边，不是矩形 Local Costmap 的精确几何边界。因此在非正方形 Costmap 中，局部 Path 可能包含落在短边外的 Pose。</p><h3 id="_2-3-局部-path-被变换到-base-frame" tabindex="-1">2.3 局部 Path 被变换到 base frame <a class="header-anchor" href="#_2-3-局部-path-被变换到-base-frame" aria-label="Permalink to &quot;2.3 局部 Path 被变换到 base frame&quot;">​</a></h3><p>截取的每个 Pose 都被变换到 Costmap 的机器人基座坐标系。此后机器人位于原点，前方是 <code>x&gt;0</code>，左侧是 <code>y&gt;0</code>。</p><p>Pure Pursuit 的前视距离、carrot 方位角、曲率和倒车方向都能直接在这个坐标系中计算，不必反复处理机器人世界位姿。</p><h3 id="_2-4-已驶过的路径会永久裁掉" tabindex="-1">2.4 已驶过的路径会永久裁掉 <a class="header-anchor" href="#_2-4-已驶过的路径会永久裁掉" aria-label="Permalink to &quot;2.4 已驶过的路径会永久裁掉&quot;">​</a></h3><p>最近点之前的全局 Path 前缀从 <code>global_plan_</code> 中删除：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global_plan_.poses.erase(begin, closest_pose)</span></span></code></pre></div><p>下个控制周期从新的路径起点继续处理。RPP 因此带有滚动路径状态，不是每周期都从原始全局路径首 Pose 重新开始。</p><h3 id="_2-5-空路径和主变换失败直接终止" tabindex="-1">2.5 空路径和主变换失败直接终止 <a class="header-anchor" href="#_2-5-空路径和主变换失败直接终止" aria-label="Permalink to &quot;2.5 空路径和主变换失败直接终止&quot;">​</a></h3><p>未设置 Path、机器人 Pose 无法变换到 Path frame，或变换后的局部 Path 为空时，RPP 都会抛出 <code>PlannerException</code>。</p><p>但逐个 Path Pose 的变换调用没有检查 <code>transformPose()</code> 返回值。单个 Pose 变换失败时，lambda 仍会返回输出对象，这是当前实现中需要额外关注的 TF 边界。</p><h2 id="三、前视距离随当前速度伸缩" tabindex="-1">三、前视距离随当前速度伸缩 <a class="header-anchor" href="#三、前视距离随当前速度伸缩" aria-label="Permalink to &quot;三、前视距离随当前速度伸缩&quot;">​</a></h2><h3 id="_3-1-固定前视模式直接使用-lookahead-dist" tabindex="-1">3.1 固定前视模式直接使用 lookahead_dist <a class="header-anchor" href="#_3-1-固定前视模式直接使用-lookahead-dist" aria-label="Permalink to &quot;3.1 固定前视模式直接使用 lookahead_dist&quot;">​</a></h3><p>关闭速度缩放时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ld = lookahead_dist</span></span></code></pre></div><p>当前 YAML 中 <code>lookahead_dist=0.45 m</code>，但当前同时配置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use_velocity_scaled_lookahead_dist = true</span></span></code></pre></div><p>所以这条固定值在当前 RPP 模式下不参与 carrot 距离计算。</p><h3 id="_3-2-速度缩放模式使用当前线速度绝对值" tabindex="-1">3.2 速度缩放模式使用当前线速度绝对值 <a class="header-anchor" href="#_3-2-速度缩放模式使用当前线速度绝对值" aria-label="Permalink to &quot;3.2 速度缩放模式使用当前线速度绝对值&quot;">​</a></h3><p>当前模式的公式为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ld = clamp(</span></span>
<span class="line"><span>  |current_vx| * lookahead_time,</span></span>
<span class="line"><span>  min_lookahead_dist,</span></span>
<span class="line"><span>  max_lookahead_dist)</span></span></code></pre></div><p>现用参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lookahead_time       = 1.5 s</span></span>
<span class="line"><span>min_lookahead_dist   = 0.25 m</span></span>
<span class="line"><span>max_lookahead_dist   = 0.75 m</span></span></code></pre></div><p>静止时 <code>Ld=0.25 m</code>；当前线速度为 <code>0.22 m/s</code> 时，<code>Ld=0.33 m</code>；当前速度达到 <code>0.50 m/s</code> 后，前视距离封顶为 <code>0.75 m</code>。</p><h3 id="_3-3-速度越快-看得越远" tabindex="-1">3.3 速度越快，看得越远 <a class="header-anchor" href="#_3-3-速度越快-看得越远" aria-label="Permalink to &quot;3.3 速度越快，看得越远&quot;">​</a></h3><p>短前视距离对局部路径变化更敏感，能够更快收敛，但也更容易把稀疏路径或定位噪声放大成角速度摆动。</p><p>长前视距离让转向更平滑，却可能切弯。速度缩放把两者结合：慢速精细跟踪时 carrot 靠近，高速运行时 carrot 前移，降低几何控制的敏感度。</p><h3 id="_3-4-当前速度只在特定分支发挥作用" tabindex="-1">3.4 当前速度只在特定分支发挥作用 <a class="header-anchor" href="#_3-4-当前速度只在特定分支发挥作用" aria-label="Permalink to &quot;3.4 当前速度只在特定分支发挥作用&quot;">​</a></h3><p>正常 Pure Pursuit 的 <code>applyConstraints()</code> 虽然保留 <code>curr_speed</code> 形参，但当前源码把它标为未使用。正常跟踪没有基于当前线速度的加速度窗口。</p><p>当前速度真正影响的是：</p><ul><li><code>|current_vx|</code> 决定速度缩放前视距离。</li><li><code>current_wz</code> 决定原地旋转单周期可达角速度。</li></ul><p>正常线速度的加减速度整形主要交给下游 Velocity Smoother。</p><h2 id="四、carrot-来自前视圆与-path-的交点" tabindex="-1">四、carrot 来自前视圆与 Path 的交点 <a class="header-anchor" href="#四、carrot-来自前视圆与-path-的交点" aria-label="Permalink to &quot;四、carrot 来自前视圆与 Path 的交点&quot;">​</a></h2><h3 id="_4-1-选点条件是欧氏半径-不是路径弧长" tabindex="-1">4.1 选点条件是欧氏半径，不是路径弧长 <a class="header-anchor" href="#_4-1-选点条件是欧氏半径-不是路径弧长" aria-label="Permalink to &quot;4.1 选点条件是欧氏半径，不是路径弧长&quot;">​</a></h3><p><code>getLookAheadPoint()</code> 从局部 Path 起点向后查找首个满足：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hypot(pose.x, pose.y) &gt;= Ld</span></span></code></pre></div><p>的 Pose。</p><p>它比较的是机器人原点到各 Pose 的直线距离，不是沿 Path 累计到该 Pose 的弧长。路径强烈弯曲时，二者可能明显不同。</p><h3 id="_4-2-path-不够长时使用末端-pose" tabindex="-1">4.2 Path 不够长时使用末端 Pose <a class="header-anchor" href="#_4-2-path-不够长时使用末端-pose" aria-label="Permalink to &quot;4.2 Path 不够长时使用末端 Pose&quot;">​</a></h3><p>如果局部 Path 中没有 Pose 到达前视半径，RPP 使用最后一个 Pose 作为 carrot。</p><p>接近路径终点时，实际 carrot 距离自然小于理想 <code>Ld</code>。后续终点接近速度缩放正是利用局部 Path 剩余长度和末点距离让机器人减速。</p><h3 id="_4-3-稀疏-path-通过圆线段交点插值" tabindex="-1">4.3 稀疏 Path 通过圆线段交点插值 <a class="header-anchor" href="#_4-3-稀疏-path-通过圆线段交点插值" aria-label="Permalink to &quot;4.3 稀疏 Path 通过圆线段交点插值&quot;">​</a></h3><p>如果启用 <code>use_interpolation=true</code>，并且找到的 Pose 不是局部 Path 首点，源码不会直接跳到这个离散 Pose。</p><p>已知：</p><ul><li>前一个 Pose 位于前视圆内。</li><li>当前 Pose 位于前视圆上或圆外。</li><li>圆心是机器人原点。</li></ul><p>RPP 解析求解路径线段与：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x² + y² = Ld²</span></span></code></pre></div><p>的交点，返回恰好距离机器人 <code>Ld</code> 的 carrot。</p><h3 id="_4-4-插值降低离散路径引起的命令跳变" tabindex="-1">4.4 插值降低离散路径引起的命令跳变 <a class="header-anchor" href="#_4-4-插值降低离散路径引起的命令跳变" aria-label="Permalink to &quot;4.4 插值降低离散路径引起的命令跳变&quot;">​</a></h3><p>如果直接取圆外的首个 Pose，Path 点间距越大，carrot 越可能在相邻控制周期突然跳跃，曲率和角速度也会跟着突变。</p><p>圆线段解析交点把离散 Path 转成连续前视目标。它没有改变原路径拓扑，只是在相邻 Pose 之间恢复一个几何连续点。</p><h2 id="五、pure-pursuit-的几何核心只有一个曲率公式" tabindex="-1">五、Pure Pursuit 的几何核心只有一个曲率公式 <a class="header-anchor" href="#五、pure-pursuit-的几何核心只有一个曲率公式" aria-label="Permalink to &quot;五、Pure Pursuit 的几何核心只有一个曲率公式&quot;">​</a></h2><p><img src="`+i+`" alt="Pure Pursuit 几何与三分支控制"></p><h3 id="_5-1-carrot-定义了唯一追踪圆" tabindex="-1">5.1 carrot 定义了唯一追踪圆 <a class="header-anchor" href="#_5-1-carrot-定义了唯一追踪圆" aria-label="Permalink to &quot;5.1 carrot 定义了唯一追踪圆&quot;">​</a></h3><p>在机器人坐标系中，carrot 坐标为 <code>(x,y)</code>。假设机器人当前航向与圆弧起点切线一致，并要求圆弧通过 carrot，可以得到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L² = x² + y²</span></span>
<span class="line"><span>kappa = 2y / L²</span></span></code></pre></div><p>其中 <code>kappa=1/R</code> 是曲率。</p><h3 id="_5-2-横向偏差决定转向符号" tabindex="-1">5.2 横向偏差决定转向符号 <a class="header-anchor" href="#_5-2-横向偏差决定转向符号" aria-label="Permalink to &quot;5.2 横向偏差决定转向符号&quot;">​</a></h3><p>carrot 位于左侧时 <code>y&gt;0</code>，曲率为正；位于右侧时 <code>y&lt;0</code>，曲率为负。</p><p>同样的前视半径下，<code>|y|</code> 越大，曲率绝对值越大。carrot 越靠近机器人，分母越小，控制器也会更激进。</p><h3 id="_5-3-极近-carrot-被当成直线" tabindex="-1">5.3 极近 carrot 被当成直线 <a class="header-anchor" href="#_5-3-极近-carrot-被当成直线" aria-label="Permalink to &quot;5.3 极近 carrot 被当成直线&quot;">​</a></h3><p>源码只有在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x² + y² &gt; 0.001</span></span></code></pre></div><p>时才计算曲率，否则令 <code>kappa=0</code>。</p><p>这避免 carrot 几乎落在机器人原点时发生除零或极端曲率。但它也形成一个很小的直线死区。</p><h3 id="_5-4-角速度在调节线速度之后计算" tabindex="-1">5.4 角速度在调节线速度之后计算 <a class="header-anchor" href="#_5-4-角速度在调节线速度之后计算" aria-label="Permalink to &quot;5.4 角速度在调节线速度之后计算&quot;">​</a></h3><p>正常跟踪分支不是先定角速度再减线速度，而是先让曲率、障碍和终点调节出最终线速度，然后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega = linear_velocity * kappa</span></span></code></pre></div><p>因此几何曲率保持不变。线速度降低时，角速度同步降低，理想运动半径仍为 <code>1/|kappa|</code>。</p><h2 id="六、三条控制分支有严格优先级" tabindex="-1">六、三条控制分支有严格优先级 <a class="header-anchor" href="#六、三条控制分支有严格优先级" aria-label="Permalink to &quot;六、三条控制分支有严格优先级&quot;">​</a></h2><h3 id="_6-1-目标航向旋转优先" tabindex="-1">6.1 目标航向旋转优先 <a class="header-anchor" href="#_6-1-目标航向旋转优先" aria-label="Permalink to &quot;6.1 目标航向旋转优先&quot;">​</a></h3><p>RPP 每周期从 GoalChecker 获取位置容差，当前为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xy_goal_tolerance = 0.25 m</span></span></code></pre></div><p>如果 carrot 到机器人原点的距离小于这个容差，并启用了 <code>use_rotate_to_heading</code>，控制器进入目标航向旋转分支。</p><p>目标角度来自局部 Path 最后一个 Pose 的 yaw，而不是 carrot 的连线方向。</p><h3 id="_6-2-路径航向旋转随后判断" tabindex="-1">6.2 路径航向旋转随后判断 <a class="header-anchor" href="#_6-2-路径航向旋转随后判断" aria-label="Permalink to &quot;6.2 路径航向旋转随后判断&quot;">​</a></h3><p>未进入目标旋转时，RPP 计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>angle_to_path = atan2(carrot.y, carrot.x)</span></span></code></pre></div><p>当前阈值为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rotate_to_heading_min_angle = 0.785 rad</span></span></code></pre></div><p>当 carrot 方位误差超过约四十五度时，控制器先原地对齐路径，再恢复 Pure Pursuit 跟踪。</p><h3 id="_6-3-正常分支才应用曲率速度调节" tabindex="-1">6.3 正常分支才应用曲率速度调节 <a class="header-anchor" href="#_6-3-正常分支才应用曲率速度调节" aria-label="Permalink to &quot;6.3 正常分支才应用曲率速度调节&quot;">​</a></h3><p>目标旋转和路径旋转都不调用 <code>applyConstraints()</code>。只有两个旋转条件都不成立时，才执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>曲率速度调节</span></span>
<span class="line"><span>→ Costmap 速度调节</span></span>
<span class="line"><span>→ 终点接近速度调节</span></span>
<span class="line"><span>→ omega = v * kappa</span></span></code></pre></div><h3 id="_6-4-三条分支共享碰撞预测" tabindex="-1">6.4 三条分支共享碰撞预测 <a class="header-anchor" href="#_6-4-三条分支共享碰撞预测" aria-label="Permalink to &quot;6.4 三条分支共享碰撞预测&quot;">​</a></h3><p>无论输出的是纯旋转还是曲率跟踪 Twist，都会进入 <code>isCollisionImminent()</code>。</p><p>所以旋转接管不是安全检查的旁路。机器人原地转动时，Footprint 扫过的区域同样要接受预测检查。</p><h2 id="七、急弯通过曲率半径闸门减速" tabindex="-1">七、急弯通过曲率半径闸门减速 <a class="header-anchor" href="#七、急弯通过曲率半径闸门减速" aria-label="Permalink to &quot;七、急弯通过曲率半径闸门减速&quot;">​</a></h2><p><img src="`+l+`" alt="曲率、障碍和终点三路速度调节"></p><h3 id="_7-1-正常分支从期望速度开始" tabindex="-1">7.1 正常分支从期望速度开始 <a class="header-anchor" href="#_7-1-正常分支从期望速度开始" aria-label="Permalink to &quot;7.1 正常分支从期望速度开始&quot;">​</a></h3><p>当前 RPP 配置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desired_linear_vel = 0.22 m/s</span></span></code></pre></div><p>正常分支把 <code>linear_vel</code> 初始化为这个值。若 Controller Server 下发 SpeedLimit，<code>desired_linear_vel_</code> 会被临时改写，成为后续所有调节的基础上限。</p><h3 id="_7-2-转弯半径小于阈值才触发" tabindex="-1">7.2 转弯半径小于阈值才触发 <a class="header-anchor" href="#_7-2-转弯半径小于阈值才触发" aria-label="Permalink to &quot;7.2 转弯半径小于阈值才触发&quot;">​</a></h3><p>源码计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R = |1 / kappa|</span></span></code></pre></div><p>当前曲率调节阈值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>regulated_linear_scaling_min_radius = 0.7 m</span></span></code></pre></div><p>当 <code>R&gt;=0.7 m</code> 时，曲率不降低线速度；当 <code>R&lt;0.7 m</code> 时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_curvature = v_desired * R / 0.7</span></span></code></pre></div><p>转弯半径减半，曲率候选速度也近似减半。</p><h3 id="_7-3-直线曲率自然跳过减速" tabindex="-1">7.3 直线曲率自然跳过减速 <a class="header-anchor" href="#_7-3-直线曲率自然跳过减速" aria-label="Permalink to &quot;7.3 直线曲率自然跳过减速&quot;">​</a></h3><p><code>kappa=0</code> 时，<code>1/kappa</code> 在浮点语义下得到无穷大，半径不会小于阈值，因此直线不会触发曲率调节。</p><p>源码没有为直线单独写一条分支，浮点无穷大在这里自然表达了“转弯半径无限大”。</p><h3 id="_7-4-曲率调节不直接限制角速度" tabindex="-1">7.4 曲率调节不直接限制角速度 <a class="header-anchor" href="#_7-4-曲率调节不直接限制角速度" aria-label="Permalink to &quot;7.4 曲率调节不直接限制角速度&quot;">​</a></h3><p>正常分支没有 <code>max_angular_vel</code> 参数，也没有角加速度窗口。即使曲率速度已经减小，最终：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega = v * kappa</span></span></code></pre></div><p>仍可能在极端小半径下得到较大的角速度。</p><p>当前下游 Velocity Smoother 配置 <code>max_velocity.theta=1.0 rad/s</code>，会继续限制最终角速度，但这属于 RPP 包外的速度链。</p><h2 id="八、近障碍速度来自-costmap-代价反解" tabindex="-1">八、近障碍速度来自 Costmap 代价反解 <a class="header-anchor" href="#八、近障碍速度来自-costmap-代价反解" aria-label="Permalink to &quot;八、近障碍速度来自 Costmap 代价反解&quot;">​</a></h2><h3 id="_8-1-读取的是机器人中心当前栅格" tabindex="-1">8.1 读取的是机器人中心当前栅格 <a class="header-anchor" href="#_8-1-读取的是机器人中心当前栅格" aria-label="Permalink to &quot;8.1 读取的是机器人中心当前栅格&quot;">​</a></h3><p>Costmap 调节使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>costAtPose(robot_pose.x, robot_pose.y)</span></span></code></pre></div><p>它读取机器人中心当前所在栅格的 Local Costmap 代价，不读取 carrot 代价，也不沿预测弧寻找最大代价。</p><p>路径前方障碍由后续 Footprint 碰撞预测负责拒绝；当前中心附近的膨胀代价负责提前降速。</p><h3 id="_8-2-inflation-代价被反解为障碍距离" tabindex="-1">8.2 Inflation 代价被反解为障碍距离 <a class="header-anchor" href="#_8-2-inflation-代价被反解为障碍距离" aria-label="Permalink to &quot;8.2 Inflation 代价被反解为障碍距离&quot;">​</a></h3><p>当中心格既不是自由空间，也不是未知空间时，RPP 使用 Inflation Layer 的指数模型反解近似障碍距离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d_obs =</span></span>
<span class="line"><span>  -ln(cost / 252) / inflation_cost_scaling_factor</span></span>
<span class="line"><span>  + inscribed_radius</span></span></code></pre></div><p>当前 RPP 与 Local Costmap 都使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inflation_cost_scaling_factor = 5.0</span></span></code></pre></div><p>两边一致，反解距离才有正确物理意义。</p><h3 id="_8-3-进入调节距离后按比例降速" tabindex="-1">8.3 进入调节距离后按比例降速 <a class="header-anchor" href="#_8-3-进入调节距离后按比例降速" aria-label="Permalink to &quot;8.3 进入调节距离后按比例降速&quot;">​</a></h3><p>当前障碍调节参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cost_scaling_dist = 0.35 m</span></span>
<span class="line"><span>cost_scaling_gain = 0.8</span></span></code></pre></div><p>当 <code>d_obs&lt;0.35 m</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_cost =</span></span>
<span class="line"><span>  v_desired * 0.8 * d_obs / 0.35</span></span></code></pre></div><p>越靠近障碍，Costmap 候选速度越低。</p><h3 id="_8-4-inflation-参数不匹配会让速度语义失真" tabindex="-1">8.4 Inflation 参数不匹配会让速度语义失真 <a class="header-anchor" href="#_8-4-inflation-参数不匹配会让速度语义失真" aria-label="Permalink to &quot;8.4 Inflation 参数不匹配会让速度语义失真&quot;">​</a></h3><p>如果 RPP 使用的 <code>inflation_cost_scaling_factor</code> 与 Local Costmap 不一致，同一个栅格代价会被反解成错误距离。</p><p>表现可能是机器人离障碍还很远就持续低速，或者已经很近却没有充分减速。排查这类问题应同时核对 RPP、Inflation Layer 和机器人 Footprint。</p><h2 id="九、终点接近缩放最后接管线速度" tabindex="-1">九、终点接近缩放最后接管线速度 <a class="header-anchor" href="#九、终点接近缩放最后接管线速度" aria-label="Permalink to &quot;九、终点接近缩放最后接管线速度&quot;">​</a></h2><h3 id="_9-1-触发条件使用局部-path-剩余积分长度" tabindex="-1">9.1 触发条件使用局部 Path 剩余积分长度 <a class="header-anchor" href="#_9-1-触发条件使用局部-path-剩余积分长度" aria-label="Permalink to &quot;9.1 触发条件使用局部 Path 剩余积分长度&quot;">​</a></h3><p>RPP 先计算局部 Path 的累计长度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>remaining_path_length =</span></span>
<span class="line"><span>  calculate_path_length(transformed_path)</span></span></code></pre></div><p>只有它小于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>approach_velocity_scaling_dist = 0.6 m</span></span></code></pre></div><p>才进入终点接近缩放。</p><p>先用路径积分长度判定，可以避免一条弯曲 Path 的末端在欧氏距离上很近，却实际仍需沿弧走较长距离时过早减速。</p><h3 id="_9-2-缩放比例使用末端欧氏距离" tabindex="-1">9.2 缩放比例使用末端欧氏距离 <a class="header-anchor" href="#_9-2-缩放比例使用末端欧氏距离" aria-label="Permalink to &quot;9.2 缩放比例使用末端欧氏距离&quot;">​</a></h3><p>触发后，缩放比例改用机器人原点到局部 Path 最后 Pose 的直线距离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scale =</span></span>
<span class="line"><span>  euclidean_distance_to_path_end / 0.6</span></span></code></pre></div><p>候选接近速度为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_approach =</span></span>
<span class="line"><span>  max(current_v * scale, min_approach_linear_velocity)</span></span></code></pre></div><p>当前最小接近速度是 <code>0.03 m/s</code>。</p><h3 id="_9-3-三路约束按特定顺序融合" tabindex="-1">9.3 三路约束按特定顺序融合 <a class="header-anchor" href="#_9-3-三路约束按特定顺序融合" aria-label="Permalink to &quot;9.3 三路约束按特定顺序融合&quot;">​</a></h3><p>源码顺序为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v = min(v_curvature, v_cost)</span></span>
<span class="line"><span>v = max(v, regulated_linear_scaling_min_speed)</span></span>
<span class="line"><span>v = min(v, v_approach)</span></span>
<span class="line"><span>v = clamp(|v|, 0, desired_linear_vel)</span></span></code></pre></div><p>当前 <code>regulated_linear_scaling_min_speed=0.05 m/s</code>，但目标接近缩放发生在这层保护之后，所以最终速度仍可降到 <code>min_approach_linear_velocity=0.03 m/s</code>。</p><h3 id="_9-4-最低速度不是整条链的统一下限" tabindex="-1">9.4 最低速度不是整条链的统一下限 <a class="header-anchor" href="#_9-4-最低速度不是整条链的统一下限" aria-label="Permalink to &quot;9.4 最低速度不是整条链的统一下限&quot;">​</a></h3><p><code>regulated_linear_scaling_min_speed</code> 只保护曲率与 Costmap 两条调节链，防止急弯或高代价把机器人直接压到无法运动。</p><p>终点接近有自己的更低下限。理解这两个参数的先后关系，才能解释为什么配置了 <code>0.05 m/s</code>，终点附近仍可能看到 <code>0.03 m/s</code>。</p><h2 id="十、原地旋转和倒车是互斥模式" tabindex="-1">十、原地旋转和倒车是互斥模式 <a class="header-anchor" href="#十、原地旋转和倒车是互斥模式" aria-label="Permalink to &quot;十、原地旋转和倒车是互斥模式&quot;">​</a></h2><p><img src="`+c+`" alt="原地旋转、倒车方向与 cusp"></p><h3 id="_10-1-原地旋转先满足角加速度窗口" tabindex="-1">10.1 原地旋转先满足角加速度窗口 <a class="header-anchor" href="#_10-1-原地旋转先满足角加速度窗口" aria-label="Permalink to &quot;10.1 原地旋转先满足角加速度窗口&quot;">​</a></h3><p>旋转分支强制：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linear_vel = 0</span></span>
<span class="line"><span>omega_target =</span></span>
<span class="line"><span>  sign(angle_error) * rotate_to_heading_angular_vel</span></span></code></pre></div><p>当前目标旋转速度为 <code>0.8 rad/s</code>。</p><p>控制频率为 <code>20 Hz</code>，所以 <code>dt=0.05 s</code>。当前角速度和最大角加速度形成单周期窗口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega ∈ [</span></span>
<span class="line"><span>  current_wz - 3.2 * 0.05,</span></span>
<span class="line"><span>  current_wz + 3.2 * 0.05</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>每周期角速度最多变化约 <code>0.16 rad/s</code>。</p><h3 id="_10-2-剩余角度还要满足刹停速度" tabindex="-1">10.2 剩余角度还要满足刹停速度 <a class="header-anchor" href="#_10-2-剩余角度还要满足刹停速度" aria-label="Permalink to &quot;10.2 剩余角度还要满足刹停速度&quot;">​</a></h3><p>单周期裁剪后，源码再计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega_stop =</span></span>
<span class="line"><span>  sqrt(2 * max_angular_accel * |angle_error|)</span></span></code></pre></div><p>如果当前候选角速度大于这个值，就降到 <code>omega_stop</code>。这是由：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega² = 2 * angular_acceleration * angle</span></span></code></pre></div><p>得到的刹停边界，用于降低接近目标航向时的过冲。</p><h3 id="_10-3-倒车必须关闭旋转接管" tabindex="-1">10.3 倒车必须关闭旋转接管 <a class="header-anchor" href="#_10-3-倒车必须关闭旋转接管" aria-label="Permalink to &quot;10.3 倒车必须关闭旋转接管&quot;">​</a></h3><p>源码不允许：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use_rotate_to_heading = true</span></span>
<span class="line"><span>allow_reversing = true</span></span></code></pre></div><p>同时成立。配置阶段会保留旋转接管并关闭倒车；动态更新阶段也会拒绝冲突组合。</p><p>当前配置启用旋转接管，<code>allow_reversing</code> 未显式设置，使用默认 <code>false</code>。</p><h3 id="_10-4-cusp-防止前视点跨过换向位置" tabindex="-1">10.4 cusp 防止前视点跨过换向位置 <a class="header-anchor" href="#_10-4-cusp-防止前视点跨过换向位置" aria-label="Permalink to &quot;10.4 cusp 防止前视点跨过换向位置&quot;">​</a></h3><p>启用倒车后，RPP 遍历局部 Path 的相邻向量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OA = pose[i]   - pose[i-1]</span></span>
<span class="line"><span>AB = pose[i+1] - pose[i]</span></span></code></pre></div><p>当：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OA · AB &lt; 0</span></span></code></pre></div><p>就把 <code>pose[i]</code> 视为速度符号切换点 cusp。如果前视距离大于机器人到 cusp 的欧氏距离，就把前视距离截短到 cusp。</p><h3 id="_10-5-carrot-的-x-决定前进还是倒车" tabindex="-1">10.5 carrot 的 x 决定前进还是倒车 <a class="header-anchor" href="#_10-5-carrot-的-x-决定前进还是倒车" aria-label="Permalink to &quot;10.5 carrot 的 x 决定前进还是倒车&quot;">​</a></h3><p>允许倒车时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>carrot.x &gt;= 0  → sign = +1</span></span>
<span class="line"><span>carrot.x &lt; 0   → sign = -1</span></span></code></pre></div><p>三路速度调节先计算正的速度幅值，末尾再乘 <code>sign</code>。随后 <code>omega=v*kappa</code>，所以线速度和角速度会一起随运动方向翻转。</p><h3 id="_10-6-尖锐折线也可能触发-cusp" tabindex="-1">10.6 尖锐折线也可能触发 cusp <a class="header-anchor" href="#_10-6-尖锐折线也可能触发-cusp" aria-label="Permalink to &quot;10.6 尖锐折线也可能触发 cusp&quot;">​</a></h3><p>点积小于零表示两段路径夹角超过九十度，并不只代表严格的一百八十度倒车换向。</p><p>如果上游路径包含没有运动学意义的尖锐折角，RPP 也可能把它当成 cusp。倒车模式应配合能表达前进／倒车方向且几何连续的规划器。</p><h2 id="十一、候选-twist-必须穿过预测碰撞弧" tabindex="-1">十一、候选 Twist 必须穿过预测碰撞弧 <a class="header-anchor" href="#十一、候选-twist-必须穿过预测碰撞弧" aria-label="Permalink to &quot;十一、候选 Twist 必须穿过预测碰撞弧&quot;">​</a></h2><p><img src="`+r+`" alt="RPP 预测碰撞弧与最终速度边界"></p><h3 id="_11-1-当前-footprint-先接受检查" tabindex="-1">11.1 当前 Footprint 先接受检查 <a class="header-anchor" href="#_11-1-当前-footprint-先接受检查" aria-label="Permalink to &quot;11.1 当前 Footprint 先接受检查&quot;">​</a></h3><p><code>isCollisionImminent()</code> 首先在机器人当前世界 Pose 上检查完整 Footprint。</p><p>如果当前姿态已经覆盖致命障碍，控制器直接判定碰撞，不再向前展开预测弧。</p><h3 id="_11-2-平移步长对应一个-costmap-栅格" tabindex="-1">11.2 平移步长对应一个 Costmap 栅格 <a class="header-anchor" href="#_11-2-平移步长对应一个-costmap-栅格" aria-label="Permalink to &quot;11.2 平移步长对应一个 Costmap 栅格&quot;">​</a></h3><p>普通路径跟踪使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>projection_dt =</span></span>
<span class="line"><span>  costmap_resolution / |linear_vel|</span></span></code></pre></div><p>于是每次一阶积分的平移距离约等于一个 Costmap 栅格：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delta_s = |v| * projection_dt</span></span>
<span class="line"><span>        = costmap_resolution</span></span></code></pre></div><p>速度越快，时间步越短，但空间采样间距保持与地图分辨率一致。</p><h3 id="_11-3-纯旋转使用独立角度步长" tabindex="-1">11.3 纯旋转使用独立角度步长 <a class="header-anchor" href="#_11-3-纯旋转使用独立角度步长" aria-label="Permalink to &quot;11.3 纯旋转使用独立角度步长&quot;">​</a></h3><p>当 <code>|v|&lt;0.01</code> 且 <code>|omega|&gt;0.01</code> 时，RPP 根据机器人外接圆半径和 Costmap 分辨率计算旋转预测时间：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>projection_dt =</span></span>
<span class="line"><span>  2 * sin((resolution / 2) / circumscribed_radius)</span></span>
<span class="line"><span>  / |omega|</span></span></code></pre></div><p>目标是让 Footprint 最外侧每次转动约一个栅格尺度，而不是沿用平移步长。</p><h3 id="_11-4-未来-pose-用一阶运动学积分" tabindex="-1">11.4 未来 Pose 用一阶运动学积分 <a class="header-anchor" href="#_11-4-未来-pose-用一阶运动学积分" aria-label="Permalink to &quot;11.4 未来 Pose 用一阶运动学积分&quot;">​</a></h3><p>每个预测步执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x += dt * v * cos(theta)</span></span>
<span class="line"><span>y += dt * v * sin(theta)</span></span>
<span class="line"><span>theta += dt * omega</span></span></code></pre></div><p>它假设候选 Twist 在整个短时域内保持不变。每个未来 Pose 都用真实机器人 Footprint 查询 Local Costmap。</p><h3 id="_11-5-预测范围受时间和-carrot-双重限制" tabindex="-1">11.5 预测范围受时间和 carrot 双重限制 <a class="header-anchor" href="#_11-5-预测范围受时间和-carrot-双重限制" aria-label="Permalink to &quot;11.5 预测范围受时间和 carrot 双重限制&quot;">​</a></h3><p>当前最大碰撞预测时间：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_allowed_time_to_collision_up_to_carrot = 1.0 s</span></span></code></pre></div><p>此外，当预测 Pose 相对机器人起点的欧氏位移超过 carrot 距离时也会停止。</p><p>所以碰撞弧不会无条件沿当前圆弧预测一秒，更不会跨过当前控制决策真正瞄准的前视目标。</p><h3 id="_11-6-碰撞命中会拒绝整条命令" tabindex="-1">11.6 碰撞命中会拒绝整条命令 <a class="header-anchor" href="#_11-6-碰撞命中会拒绝整条命令" aria-label="Permalink to &quot;11.6 碰撞命中会拒绝整条命令&quot;">​</a></h3><p>任一未来 Footprint 的代价达到致命障碍阈值，RPP 发布已预测的碰撞弧并抛出 <code>PlannerException</code>。</p><p>Controller Server 决定是否在失败容忍窗口内暂时发布零速、重新调用控制器或最终终止 FollowPath。RPP 自己不返回一个“更慢但可用”的备选 Twist。</p><h2 id="十二、核心算法之外还有四条速度与安全边界" tabindex="-1">十二、核心算法之外还有四条速度与安全边界 <a class="header-anchor" href="#十二、核心算法之外还有四条速度与安全边界" aria-label="Permalink to &quot;十二、核心算法之外还有四条速度与安全边界&quot;">​</a></h2><h3 id="_12-1-正常跟踪没有本地角速度上限" tabindex="-1">12.1 正常跟踪没有本地角速度上限 <a class="header-anchor" href="#_12-1-正常跟踪没有本地角速度上限" aria-label="Permalink to &quot;12.1 正常跟踪没有本地角速度上限&quot;">​</a></h3><p>RPP 的 <code>rotate_to_heading_angular_vel</code> 只用于原地旋转分支，不会限制正常 Pure Pursuit 的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>omega = v * kappa</span></span></code></pre></div><p>当前 Controller Server 输出先进入 <code>cmd_vel_nav</code>，再由 CLOSED_LOOP Velocity Smoother 按：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_velocity = [0.26, 0.0, 1.0]</span></span></code></pre></div><p>继续限制线速度、横向速度和角速度，最后发布 <code>cmd_vel</code>。</p><h3 id="_12-2-speedlimit-改写的是期望线速度" tabindex="-1">12.2 SpeedLimit 改写的是期望线速度 <a class="header-anchor" href="#_12-2-speedlimit-改写的是期望线速度" aria-label="Permalink to &quot;12.2 SpeedLimit 改写的是期望线速度&quot;">​</a></h3><p>百分比限速按基础 <code>desired_linear_vel</code> 缩放，绝对限速直接写入当前期望速度。取消限速时恢复基础值。</p><p>当前 <code>setSpeedLimit()</code> 不获取 RPP 参数 mutex，而且绝对限速没有强制限制在基础速度以下。外部调用方需要保证 SpeedLimit 语义正确。</p><h3 id="_12-3-costmap-外预测点被视为无碰撞" tabindex="-1">12.3 Costmap 外预测点被视为无碰撞 <a class="header-anchor" href="#_12-3-costmap-外预测点被视为无碰撞" aria-label="Permalink to &quot;12.3 Costmap 外预测点被视为无碰撞&quot;">​</a></h3><p>碰撞预测 Pose 无法转换到 Costmap 栅格时，源码记录节流告警并返回 <code>false</code>。</p><p>这意味着预测弧越出 Local Costmap 不是“未知即危险”，而是继续按无碰撞处理。实车上应让 Costmap 尺寸、速度和预测时间相互匹配。</p><h3 id="_12-4-跟踪未知空间时-no-information-可视为安全" tabindex="-1">12.4 跟踪未知空间时 NO_INFORMATION 可视为安全 <a class="header-anchor" href="#_12-4-跟踪未知空间时-no-information-可视为安全" aria-label="Permalink to &quot;12.4 跟踪未知空间时 NO_INFORMATION 可视为安全&quot;">​</a></h3><p>Footprint 代价为 <code>NO_INFORMATION</code> 且 LayeredCostmap 正在跟踪未知空间时，<code>inCollision()</code> 返回 <code>false</code>。</p><p>这与地图边界行为叠加后，可能让预测弧在未知或覆盖不足区域继续执行。是否接受这种策略，取决于定位、传感器覆盖和具体安全要求。</p><h3 id="_12-5-一根-carrot-背后其实是完整控制闭环" tabindex="-1">12.5 一根 carrot 背后其实是完整控制闭环 <a class="header-anchor" href="#_12-5-一根-carrot-背后其实是完整控制闭环" aria-label="Permalink to &quot;12.5 一根 carrot 背后其实是完整控制闭环&quot;">​</a></h3><p>RPP 的核心不是复杂搜索，而是把简单几何放进正确的约束顺序：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>局部 Path</span></span>
<span class="line"><span>→ 动态前视 carrot</span></span>
<span class="line"><span>→ Pure Pursuit 曲率</span></span>
<span class="line"><span>→ 旋转／跟踪分支</span></span>
<span class="line"><span>→ 急弯、近障碍、近终点减速</span></span>
<span class="line"><span>→ Footprint 预测碰撞</span></span>
<span class="line"><span>→ RPP Twist</span></span>
<span class="line"><span>→ Velocity Smoother</span></span>
<span class="line"><span>→ 底盘 cmd_vel</span></span></code></pre></div><p>carrot 决定机器人想去哪里，曲率决定如何转过去，三路速度闸门决定该跑多快，预测碰撞弧则拥有最后否决权。</p><p>这正是 Regulated Pure Pursuit 比普通 Pure Pursuit 多出来的工程价值。</p>`,266)])])}const x=e(d,[["render",h]]);export{P as __pageData,x as default};
